head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gLdMktTp;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF10904.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_init = function() {

};
scwin.fn_SetHeader = function() {
    // CUD용 Header
    dts_Save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MKTACT_NOTICE_IN";
    dts_Save.Reset();
    dts_Save.insertRow();
};
scwin.fn_SetCode = function() {
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅	
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_FromDate.text = cGetMinusDate2(vCurDate, 365); 	// 일주일전 날짜
    edt_FromDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};
scwin.fn_Search = function() {
    var url = "/MktActNotice.do?method=listMarketActionNoticeBnd" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&SDATE=" + $c.stf.getObjectValue(edt_FromDate) + "&EDATE=" + $c.stf.getObjectValue(edt_ToDate) + "&HALT_DESNRELS_TP_CD=" + $c.stf.getObjectValue(rdo_HALT_DESNRELS_TP_CD) + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.reset();
    $c.cm.ShowWin(grd_Grid);
};
scwin.fn_Confirm = function(row, colid) {
    if ((colid == "CONFIRM_YN") && (row > 0) && (dts_Grid.getCellData(row, "CONFIRM_YN") != "")) {
        var res = window.confirm("확인 하시겠습니까?");
        if (res) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            LastJob = "확인";
            var str_NOTI_SEQ = dts_Grid.getCellData(row, "NOTI_SEQ");
            var str_BZ_PROCS_NO = dts_Grid.getCellData(row, "BZ_PROCS_NO");
            var str_ACPTR_EMP_NO = js_id; /*ORG SRC: dts_Save.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
            dts_Save.setCellData(1, "NOTI_SEQ", str_NOTI_SEQ);
            dts_Save.setCellData(1, "BZ_PROCS_NO", str_BZ_PROCS_NO);
            dts_Save.setCellData(1, "ACPTR_EMP_NO", str_ACPTR_EMP_NO);
            trs_Save.Action = "/MktActNotice.do?method=updateConfirmBnd" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_Save)";
            trs_Save.Post();
        }
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    if (colid == 'CONFIRM_YN') {
        // 채권상장공시팀만 확인 처리 가능
        if (js_dep_cd == '2430') {
            if (dts_Grid.getCellData(row, colid) == '[확인]') {
                scwin.fn_Confirm(row, colid);
            }
        }
    } else if (colid == 'COM_ABBRV') {
        scwin.gIsurCd = dts_Grid.getCellData(row, "ISUR_CD");
        scwin.gIsurCd = scwin.gIsurCd.substring(0, 5);
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    if (dts_Grid.errorMsg) {
        $c.win.alert(dts_Grid.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_Grid, '시장조치내역', '', 8);
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert(LastJob + " 실패");
    $c.stf.alert_error(trs_Save);
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.

};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert("확인 하였습니다.");
    dts_Save.Reset();
    dts_Save.insertRow(); // 성공일 때 Default로 한줄 추가해 놓는다.
    scwin.fn_Search();
};
scwin.btn_notiObj_onclick = async function() {
    await $c.frame.CreateDialogFrame("gform", "/dsclproc/ULDSTF10905.gfm", "통보대상 매매거래정지 코드", 50, 50, 1060, 688, "window");
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_SetHeader();
    scwin.fn_init();
    scwin.fn_Search();
};
